/**
 * Node procedure-dispatch installer.
 *
 * Owns the NAPI callbacks that the shared JS shim
 * (`galley_install_js_dispatch_id`, generated by `@sanbus/galley-core/build/shim.mjs`)
 * forwards every parser hook through. The hook tables live in the core —
 * one per session; this module only bridges the native boundary, with one
 * callback closure per loaded library so two grammars in one process
 * never share a port or a name table. Libraries that predate integer
 * hook IDs still export the name-carrying `galley_install_js_dispatch`,
 * used as a fallback.
 */

import * as path from "node:path";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);

import { loadProceduresModule } from "@sanbus/galley-core";
import type { FfiPort } from "@sanbus/galley-core";
import type { GalleyFFI } from "./ffi.ts";

// Held to prevent GC of the installed callbacks; installed per library
// path. The addon also retains them, but the address must stay reachable
// here too. ID and name paths keep separate slots: their signatures
// differ. Per-path (not singletons): each closure captures its own
// library's port and name table.
const idCallbacks = new Map<string, (id: number, args: bigint) => void>();
const nameCallbacks = new Map<string, (name: string, args: bigint) => void>();
const installedFor = new Set<string>();

/**
 * Synchronously loads the language directory's `procedures` module, if
 * any. Returns the module for the session to install into its own
 * registry; never touches another session's hooks.
 */
export function loadProcedures(languagePath: string): Record<string, unknown> | null {
  return loadProceduresModule(
    (specifier) => require(specifier) as unknown,
    path.join,
    languagePath,
  );
}

/**
 * Loads the `procedures` module beside an explicit artifact file (the
 * file's own directory), for `Session.fromFile`. Same rule as the
 * directory scan; never touches another session's hooks.
 */
export function loadProceduresForFile(filePath: string): Record<string, unknown> | null {
  return loadProceduresModule(
    (specifier) => require(specifier) as unknown,
    path.join,
    path.dirname(filePath),
  );
}

export function ensureDispatchFor(foreignInterface: GalleyFFI, port: FfiPort): void {
  const useIds =
    foreignInterface.api.install_id_dispatch !== null &&
    typeof port.procedureNames === "function" &&
    port.procedureNames().length > 0;
  if (!useIds && foreignInterface.api.install_name_dispatch === null) {
    // No dispatch — installs stay no-ops.
    return;
  }
  if (installedFor.has(foreignInterface.libPath)) return;
  if (useIds) {
    installIdDispatch(foreignInterface, port);
  } else {
    installNameDispatch(foreignInterface, port);
  }
  installedFor.add(foreignInterface.libPath);
}

function installIdDispatch(foreignInterface: GalleyFFI, port: FfiPort): void {
  // Integer hook IDs; unknown IDs are silent no-ops.
  const table = port.procedureNames();
  const callback = (id: number, args: bigint) => {
    const name = table[id];
    if (name === undefined) return;
    port.activeDispatch?.(name, args);
  };
  idCallbacks.set(foreignInterface.libPath, callback);
  foreignInterface.api.install_id_dispatch!(callback);
}

function installNameDispatch(foreignInterface: GalleyFFI, port: FfiPort): void {
  // The addon decodes the hook name before crossing; the callback gets
  // the string and the raw args address.
  const callback = (name: string, args: bigint) => {
    port.activeDispatch?.(name, args);
  };
  nameCallbacks.set(foreignInterface.libPath, callback);
  foreignInterface.api.install_name_dispatch!(callback);
}
